#include "2mm.h"


void kernel_2mm(   
		double alpha,
		double beta,
		double tmp[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double C[ NJ + 0][NL + 0],
		double D[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B   offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=C   offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=D   offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=tmp   bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=B     bundle=control
#pragma HLS INTERFACE s_axilite port=C     bundle=control
#pragma HLS INTERFACE s_axilite port=D     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;

  int i, j, k;

  // ---- First matrix product: tmp = alpha * A * B ----
  // Stage one row of A locally for reuse across all columns j.
  for (i = 0; i < ni; i++)
  {
    double A_row[NK];
#pragma HLS ARRAY_PARTITION variable=A_row complete dim=1
    for (k = 0; k < nk; ++k) {
#pragma HLS PIPELINE II=1
      A_row[k] = A[i][k];
    }

    for (j = 0; j < nj; j++)
    {
#pragma HLS PIPELINE II=1
      double acc = 0.0;
      for (k = 0; k < nk; ++k) {
#pragma HLS UNROLL
        acc += alpha * A_row[k] * B[k][j];
      }
      tmp[i][j] = acc;
    }
  }

  // ---- Second matrix product: D = beta * D + tmp * C ----
  for (i = 0; i < ni; i++)
  {
    double tmp_row[NJ];
#pragma HLS ARRAY_PARTITION variable=tmp_row complete dim=1
    for (k = 0; k < nj; ++k) {
#pragma HLS PIPELINE II=1
      tmp_row[k] = tmp[i][k];
    }

    for (j = 0; j < nl; j++)
    {
#pragma HLS PIPELINE II=1
      double acc = D[i][j] * beta;
      for (k = 0; k < nj; ++k) {
#pragma HLS UNROLL
        acc += tmp_row[k] * C[k][j];
      }
      D[i][j] = acc;
    }
  }
}

#include "3mm.h"


extern "C" {
void kernel_3mm(    
		double E[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double F[ NJ + 0][NL + 0],
		double C[ NJ + 0][NM + 0],
		double D[ NM + 0][NL + 0],
		double G[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=E offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=F offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=D offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=G offset=slave bundle=gmem6
#pragma HLS INTERFACE s_axilite port=E bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=F bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=D bundle=control
#pragma HLS INTERFACE s_axilite port=G bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control


    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;
    const int nm = NM;

  int i, j, k;

    // Local buffers to enable reuse and parallel access
    double l_A[NI][NK];
    double l_B[NK][NJ];
    double l_E[NI][NJ];
    double l_C[NJ][NM];
    double l_D[NM][NL];
    double l_F[NJ][NL];
    double l_G[NI][NL];
#pragma HLS ARRAY_PARTITION variable=l_A cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_B cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_C cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_D cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_E cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_F cyclic factor=8 dim=1

    // Load A
    LOAD_A_I: for (i = 0; i < ni; i++)
      LOAD_A_K: for (k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
        l_A[i][k] = A[i][k];
      }

    // Load B
    LOAD_B_K: for (k = 0; k < nk; k++)
      LOAD_B_J: for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
        l_B[k][j] = B[k][j];
      }

    // Load C
    LOAD_C_I: for (i = 0; i < nj; i++)
      LOAD_C_K: for (k = 0; k < nm; k++) {
#pragma HLS PIPELINE II=1
        l_C[i][k] = C[i][k];
      }

    // Load D
    LOAD_D_K: for (k = 0; k < nm; k++)
      LOAD_D_J: for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
        l_D[k][j] = D[k][j];
      }

  // E := A*B
  E_I: for (i = 0; i < ni; i++)
    E_J: for (j = 0; j < nj; j++)
      {
#pragma HLS PIPELINE II=1
	double acc = 0.0;
	E_K: for (k = 0; k < nk; ++k) {
#pragma HLS UNROLL factor=8
	  acc += l_A[i][k] * l_B[k][j];
        }
	l_E[i][j] = acc;
      }

  // F := C*D
  F_I: for (i = 0; i < nj; i++)
    F_J: for (j = 0; j < nl; j++)
      {
#pragma HLS PIPELINE II=1
	double acc = 0.0;
	F_K: for (k = 0; k < nm; ++k) {
#pragma HLS UNROLL factor=8
	  acc += l_C[i][k] * l_D[k][j];
        }
	l_F[i][j] = acc;
      }

  // G := E*F
  G_I: for (i = 0; i < ni; i++)
    G_J: for (j = 0; j < nl; j++)
      {
#pragma HLS PIPELINE II=1
	double acc = 0.0;
	G_K: for (k = 0; k < nj; ++k) {
#pragma HLS UNROLL factor=8
	  acc += l_E[i][k] * l_F[k][j];
        }
	l_G[i][j] = acc;
      }

    // Store E
    STORE_E_I: for (i = 0; i < ni; i++)
      STORE_E_J: for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
        E[i][j] = l_E[i][j];
      }

    // Store F
    STORE_F_I: for (i = 0; i < nj; i++)
      STORE_F_J: for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
        F[i][j] = l_F[i][j];
      }

    // Store G
    STORE_G_I: for (i = 0; i < ni; i++)
      STORE_G_J: for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
        G[i][j] = l_G[i][j];
      }

}
}

#include "atax.h"


void kernel_atax( 
		 double A[ M + 0][N + 0],
		 double x[ N + 0],
		 double y[ N + 0],
		 double tmp[ M + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=tmp bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int m = M;
    const int n = N;

  int i, j;

  // Local buffers to enable reuse and parallel access
  double x_local[N];
  double y_local[N];
#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=y_local cyclic factor=8 dim=1

  // Stage x into local memory and initialize y_local
LOAD_X:
  for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
    x_local[j] = x[j];
  }

INIT_Y:
  for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    y_local[i] = 0;
  }

OUTER:
  for (i = 0; i < m; i++)
    {
      double A_row[N];
#pragma HLS ARRAY_PARTITION variable=A_row cyclic factor=8 dim=1

      // Stage the current row of A into local memory for reuse
    LOAD_ROW:
      for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        A_row[j] = A[i][j];
      }

      double t = 0.0;
    DOT:
      for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
        t = t + A_row[j] * x_local[j];
      }
      tmp[i] = t;

    ACCUM_Y:
      for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
        y_local[j] = y_local[j] + A_row[j] * t;
      }
    }

  // Write back y
STORE_Y:
  for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
    y[j] = y_local[j];
  }

}

#include "bicg.h"


void kernel_bicg(
		 double A[ N + 0][M + 0],
		 double s[ M + 0],
		 double q[ N + 0],
		 double p[ M + 0],
		 double r[ N + 0])
{
#pragma HLS INLINE off

    const int n = N;
    const int m = M;

  int i, j;

  // Local buffers to enable reuse and avoid repeated global memory access
  double s_local[M];
  double p_local[M];
#pragma HLS ARRAY_PARTITION variable=s_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=p_local cyclic factor=8 dim=1

init_s:
  for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
    s_local[i] = 0;
  }

load_p:
  for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
    p_local[j] = p[j];
  }

main_i:
  for (i = 0; i < n; i++)
    {
      double r_i = r[i];
      double q_acc = 0.0;

    inner_j:
      for (j = 0; j < m; j++)
	{
#pragma HLS PIPELINE II=1
	  double a_ij = A[i][j];
	  s_local[j] = s_local[j] + r_i * a_ij;
	  q_acc = q_acc + a_ij * p_local[j];
	}
      q[i] = q_acc;
    }

store_s:
  for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
    s[j] = s_local[j];
  }

}


