#include "cholesky.h"


void kernel_cholesky(
		     double A[ N + 0][N + 0])
{


    const int n = N;
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

  int i, j, k;

  // Stage the matrix into a local buffer to enable reuse and avoid
  // repeated global-memory accesses across the triangular update.
  static double L[N][N];
#pragma HLS ARRAY_PARTITION variable=L cyclic factor=8 dim=2

  // Copy input from global memory into local buffer.
  for (i = 0; i < n; i++) {
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      L[i][j] = A[i][j];
    }
  }

  for (i = 0; i < n; i++) {

     for (j = 0; j < i; j++) {
        double acc = L[i][j];
        for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
           acc -= L[i][k] * L[j][k];
        }
        L[i][j] = acc / L[j][j];
     }

     double diag = L[i][i];
     for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
        diag -= L[i][k] * L[i][k];
     }
     L[i][i] = sqrt(diag);
  }

  // Write the result back to global memory.
  for (i = 0; i < n; i++) {
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      A[i][j] = L[i][j];
    }
  }

}

#include "correlation.h"

void kernel_correlation( 
			double float_n,
			double data[ N + 0][M + 0],
			double corr[ M + 0][M + 0],
			double mean[ M + 0],
			double stddev[ M + 0])
{
#pragma HLS INTERFACE m_axi port=data   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=corr   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=mean   offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=stddev offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=float_n bundle=control
#pragma HLS INTERFACE s_axilite port=data    bundle=control
#pragma HLS INTERFACE s_axilite port=corr    bundle=control
#pragma HLS INTERFACE s_axilite port=mean    bundle=control
#pragma HLS INTERFACE s_axilite port=stddev  bundle=control
#pragma HLS INTERFACE s_axilite port=return  bundle=control

    const int n = N;
    const int m = M;

  int i, j, k;

  double eps = 0.1;

  // Local buffers to stage global memory for reuse
  static double l_data[N][M];
#pragma HLS ARRAY_PARTITION variable=l_data cyclic factor=8 dim=2
  static double l_mean[M];
#pragma HLS ARRAY_PARTITION variable=l_mean cyclic factor=8 dim=1
  static double l_stddev[M];
#pragma HLS ARRAY_PARTITION variable=l_stddev cyclic factor=8 dim=1

  // Stage data into local memory
  LOAD_I: for (i = 0; i < n; i++) {
    LOAD_J: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
      l_data[i][j] = data[i][j];
    }
  }

  // Compute mean
  MEAN_J: for (j = 0; j < m; j++)
    {
      double acc = 0.0;
      MEAN_I: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
	acc += l_data[i][j];
      }
      l_mean[j] = acc / float_n;
    }

  // Compute stddev
  STDDEV_J: for (j = 0; j < m; j++)
    {
      double acc = 0.0;
      double mj = l_mean[j];
      STDDEV_I: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        double diff = l_data[i][j] - mj;
        acc += diff * diff;
      }
      acc /= float_n;
      acc = sqrt(acc);
      l_stddev[j] = acc <= eps ? 1.0 : acc;
    }

  // Normalize data
  double sqrt_fn = sqrt(float_n);
  NORM_I: for (i = 0; i < n; i++)
    NORM_J: for (j = 0; j < m; j++)
      {
#pragma HLS PIPELINE II=1
        double v = l_data[i][j] - l_mean[j];
        v /= sqrt_fn * l_stddev[j];
        l_data[i][j] = v;
      }

  // Compute correlation matrix
  CORR_I: for (i = 0; i < m-1; i++)
    {
      corr[i][i] = 1.0;
      CORR_J: for (j = i+1; j < m; j++)
        {
          double acc = 0.0;
          CORR_K: for (k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
            acc += (l_data[k][i] * l_data[k][j]);
          }
          corr[i][j] = acc;
          corr[j][i] = acc;
        }
    }
  corr[m-1][m-1] = 1.0;

  // Write back normalized data and statistics
  STORE_I: for (i = 0; i < n; i++) {
    STORE_J: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
      data[i][j] = l_data[i][j];
    }
  }
  STORE_STATS: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
    mean[j] = l_mean[j];
    stddev[j] = l_stddev[j];
  }
}

#include "covariance.h"

extern "C" {
void kernel_covariance(
		       double float_n,
		       double data[ N + 0][M + 0],
		       double cov[ M + 0][M + 0],
		       double mean[ M + 0])
{
#pragma HLS INTERFACE m_axi port=data offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=cov  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=mean offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=float_n bundle=control
#pragma HLS INTERFACE s_axilite port=data    bundle=control
#pragma HLS INTERFACE s_axilite port=cov     bundle=control
#pragma HLS INTERFACE s_axilite port=mean    bundle=control
#pragma HLS INTERFACE s_axilite port=return  bundle=control

    const int n = N;
    const int m = M;

  int i, j, k;

  // Local staging buffers for reuse across the multiple passes.
  static double data_local[N][M];
#pragma HLS ARRAY_PARTITION variable=data_local cyclic factor=8 dim=2
  static double mean_local[M];
#pragma HLS ARRAY_PARTITION variable=mean_local cyclic factor=8 dim=1

  // Stage input data into local memory.
  load_data_i:
  for (i = 0; i < n; i++) {
    load_data_j:
    for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
      data_local[i][j] = data[i][j];
    }
  }

  // Compute means.
  mean_j:
  for (j = 0; j < m; j++) {
    double acc = 0.0;
    mean_i:
    for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
      acc += data_local[i][j];
    }
    mean_local[j] = acc / float_n;
    mean[j] = mean_local[j];
  }

  // Center the data.
  center_i:
  for (i = 0; i < n; i++) {
    center_j:
    for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
      data_local[i][j] -= mean_local[j];
    }
  }

  // Covariance computation.
  cov_i:
  for (i = 0; i < m; i++) {
    cov_j:
    for (j = i; j < m; j++) {
      double acc = 0.0;
      cov_k:
      for (k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
        acc += data_local[k][i] * data_local[k][j];
      }
      acc /= (float_n - 1.0);
      cov[i][j] = acc;
      cov[j][i] = acc;
    }
  }

}
}

#include "doitgen.h"

extern "C" {
void kernel_doitgen(
		    double A[ NR + 0][NQ + 0][NP + 0],
		    double C4[ NP + 0][NP + 0],
		    double sum[ NP + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=C4  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=sum offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=A   bundle=control
#pragma HLS INTERFACE s_axilite port=C4  bundle=control
#pragma HLS INTERFACE s_axilite port=sum bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int nr = NR;
    const int nq = NQ;
    const int np = NP;

  int r, q, p, s;

  // Local staging buffers for reuse within each (r,q) iteration.
  double C4_local[NP][NP];
#pragma HLS ARRAY_PARTITION variable=C4_local complete dim=1

  double a_local[NP];
#pragma HLS ARRAY_PARTITION variable=a_local complete dim=1

  double sum_local[NP];
#pragma HLS ARRAY_PARTITION variable=sum_local complete dim=1

  // Stage C4 once: it is reused across all (r,q).
  for (s = 0; s < np; s++) {
    for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
      C4_local[s][p] = C4[s][p];
    }
  }

  for (r = 0; r < nr; r++) {
    for (q = 0; q < nq; q++)  {

      // Load A[r][q][*] into local buffer for reuse in reduction.
      for (s = 0; s < np; s++) {
#pragma HLS PIPELINE II=1
        a_local[s] = A[r][q][s];
      }

      // Compute sum[p] = sum_s A[r][q][s] * C4[s][p]
      for (p = 0; p < np; p++)  {
#pragma HLS PIPELINE II=1
        double acc = 0.0;
        for (s = 0; s < np; s++) {
#pragma HLS UNROLL
          acc += a_local[s] * C4_local[s][p];
        }
        sum_local[p] = acc;
      }

      // Write back results into A and external sum.
      for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
        A[r][q][p] = sum_local[p];
        sum[p] = sum_local[p];
      }
    }
  }

}
}

#include "durbin.h"


void kernel_durbin(
		   double r[ N + 0],
		   double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=r offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=r bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

 double z[N];
 double alpha;
 double beta;
 double sum;

 // Local staging buffers to enable parallel access and pipelining
 double r_local[N];
 double y_local[N];
#pragma HLS ARRAY_PARTITION variable=z cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=r_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=y_local cyclic factor=8 dim=1

 int i,k;

 // Load r into local buffer
 load_r: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
   r_local[i] = r[i];
 }

 y_local[0] = -r_local[0];
 beta = 1.0;
 alpha = -r_local[0];

 for (k = 1; k < n; k++) {
   beta = (1-alpha*alpha)*beta;
   sum = 0.0;
   sum_loop: for (i=0; i<k; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=1 max=N
      sum += r_local[k-i-1]*y_local[i];
   }
   alpha = - (r_local[k] + sum)/beta;

   update_z: for (i=0; i<k; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=1 max=N
      z[i] = y_local[i] + alpha*y_local[k-i-1];
   }
   copy_y: for (i=0; i<k; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=1 max=N
     y_local[i] = z[i];
   }
   y_local[k] = alpha;
 }

 // Store result back to global memory
 store_y: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
   y[i] = y_local[i];
 }

}

#include "fdtd-2d.h"


void kernel_fdtd_2d(


		    double ex[ NX + 0][NY + 0],
		    double ey[ NX + 0][NY + 0],
		    double hz[ NX + 0][NY + 0],
		    double _fict_[ TMAX + 0])
{
#pragma HLS INTERFACE m_axi port=ex offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=ey offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=hz offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=_fict_ offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=ex bundle=control
#pragma HLS INTERFACE s_axilite port=ey bundle=control
#pragma HLS INTERFACE s_axilite port=hz bundle=control
#pragma HLS INTERFACE s_axilite port=_fict_ bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control


    const int tmax = TMAX;
    const int nx = NX;
    const int ny = NY;

  int t, i, j;


  for(t = 0; t < tmax; t++)
    {
      for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
	ey[0][j] = _fict_[t];
      }
      for (i = 1; i < nx; i++)
	for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
	  ey[i][j] = ey[i][j] - 0.5*(hz[i][j]-hz[i-1][j]);
	}
      for (i = 0; i < nx; i++)
	for (j = 1; j < ny; j++) {
#pragma HLS PIPELINE II=1
	  ex[i][j] = ex[i][j] - 0.5*(hz[i][j]-hz[i][j-1]);
	}
      for (i = 0; i < nx - 1; i++)
	for (j = 0; j < ny - 1; j++) {
#pragma HLS PIPELINE II=1
	  hz[i][j] = hz[i][j] - 0.7*  (ex[i][j+1] - ex[i][j] +
				       ey[i+1][j] - ey[i][j]);
	}
    }

}

#include "floyd-warshall.h"


void kernel_floyd_warshall(
			   int path[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=path offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=path bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j, k;

  // Local buffers to cache the k-th row and k-th column for the current k.
  // This removes repeated reads of path[k][j] and path[i][k] from the
  // pipelined inner loop, avoiding memory-port conflicts.
  int row_k[N];
  int col_k[N];
#pragma HLS ARRAY_PARTITION variable=row_k cyclic factor=8 dim=1

  for (k = 0; k < n; k++)
    {
      // Stage the k-th row and k-th column into local memory.
    cache_k:
      for (int t = 0; t < n; t++)
	{
#pragma HLS PIPELINE II=1
	  row_k[t] = path[k][t];
	  col_k[t] = path[t][k];
	}

      for(i = 0; i < n; i++)
	{
	  int pik = col_k[i];
	row_loop:
	  for (j = 0; j < n; j++)
	    {
#pragma HLS PIPELINE II=1
	      int via = pik + row_k[j];
	      int cur = path[i][j];
	      path[i][j] = cur < via ? cur : via;
	    }
	}
    }

}

#include "gemm.h"


void kernel_gemm(  
		 double alpha,
		 double beta,
		 double C[ NI + 0][NJ + 0],
		 double A[ NI + 0][NK + 0],
		 double B[ NK + 0][NJ + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;

    int i, j, k;

    // Local buffers to stage the working set for reuse and parallel access.
    double a_row[NK];
    double b_buf[NK][NJ];
    double c_row[NJ];
#pragma HLS ARRAY_PARTITION variable=a_row cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=b_buf cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=c_row cyclic factor=8 dim=1

    // Stage B once (reused across all rows of C).
    for (k = 0; k < nk; k++) {
        for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            b_buf[k][j] = B[k][j];
        }
    }

    for (i = 0; i < ni; i++) {
        // Load and scale current C row by beta.
        for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            c_row[j] = C[i][j] * beta;
        }

        // Load current A row.
        for (k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
            a_row[k] = A[i][k];
        }

        // Accumulate the matrix product into the local C row.
        for (k = 0; k < nk; k++) {
            double a_val = alpha * a_row[k];
            for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
                c_row[j] += a_val * b_buf[k][j];
            }
        }

        // Write the C row back.
        for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            C[i][j] = c_row[j];
        }
    }
}

#include "gemver.h"


void kernel_gemver(
		   double alpha,
		   double beta,
		   double A[ N + 0][N + 0],
		   double u1[ N + 0],
		   double v1[ N + 0],
		   double u2[ N + 0],
		   double v2[ N + 0],
		   double w[ N + 0],
		   double x[ N + 0],
		   double y[ N + 0],
		   double z[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=u1  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=v1  offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=u2  offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=v2  offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=w   offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=x   offset=slave bundle=gmem6
#pragma HLS INTERFACE m_axi port=y   offset=slave bundle=gmem7
#pragma HLS INTERFACE m_axi port=z   offset=slave bundle=gmem8

#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=u1    bundle=control
#pragma HLS INTERFACE s_axilite port=v1    bundle=control
#pragma HLS INTERFACE s_axilite port=u2    bundle=control
#pragma HLS INTERFACE s_axilite port=v2    bundle=control
#pragma HLS INTERFACE s_axilite port=w     bundle=control
#pragma HLS INTERFACE s_axilite port=x     bundle=control
#pragma HLS INTERFACE s_axilite port=y     bundle=control
#pragma HLS INTERFACE s_axilite port=z     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control


    const int n = N;

  int i, j;

  // Stage scalar/vector working sets locally for reuse across the loop nests.
  double l_u1[N], l_v1[N], l_u2[N], l_v2[N];
  double l_x[N], l_y[N], l_z[N], l_w[N];
  double l_A[N][N];

#pragma HLS ARRAY_PARTITION variable=l_v1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_v2 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_x  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_y  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_A  cyclic factor=8 dim=2

  // ---- Load vectors ----
LOAD_VEC:
  for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    l_u1[i] = u1[i];
    l_v1[i] = v1[i];
    l_u2[i] = u2[i];
    l_v2[i] = v2[i];
    l_x[i]  = x[i];
    l_y[i]  = y[i];
    l_z[i]  = z[i];
    l_w[i]  = w[i];
  }

  // ---- Load A ----
LOAD_A_I:
  for (i = 0; i < n; i++)
LOAD_A_J:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      l_A[i][j] = A[i][j];
    }

  // ---- A = A + u1*v1 + u2*v2 ----
K1_I:
  for (i = 0; i < n; i++) {
    double tu1 = l_u1[i];
    double tu2 = l_u2[i];
K1_J:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
      l_A[i][j] = l_A[i][j] + tu1 * l_v1[j] + tu2 * l_v2[j];
    }
  }

  // ---- x = x + beta * A^T * y ----
K2_I:
  for (i = 0; i < n; i++) {
    double acc = l_x[i];
K2_J:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      acc = acc + beta * l_A[j][i] * l_y[j];
    }
    l_x[i] = acc;
  }

  // ---- x = x + z ----
K3:
  for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    l_x[i] = l_x[i] + l_z[i];
  }

  // ---- w = w + alpha * A * x ----
K4_I:
  for (i = 0; i < n; i++) {
    double acc = l_w[i];
K4_J:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      acc = acc + alpha * l_A[i][j] * l_x[j];
    }
    l_w[i] = acc;
  }

  // ---- Store results back ----
STORE_A_I:
  for (i = 0; i < n; i++)
STORE_A_J:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      A[i][j] = l_A[i][j];
    }

STORE_VEC:
  for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    x[i] = l_x[i];
    w[i] = l_w[i];
  }

}

#include "gesummv.h"


void kernel_gesummv(
		    double alpha,
		    double beta,
		    double A[ N + 0][N + 0],
		    double B[ N + 0][N + 0],
		    double tmp[ N + 0],
		    double x[ N + 0],
		    double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem2

#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=tmp bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j;

  // Stage x locally for reuse across all rows
  double x_local[N];
#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=8 dim=1
  for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
    x_local[j] = x[j];
  }

  for (i = 0; i < n; i++)
    {
      double acc_tmp = 0.0;
      double acc_y = 0.0;

      // Stage one row of A and B locally for reuse / parallel access
      double A_row[N];
      double B_row[N];
#pragma HLS ARRAY_PARTITION variable=A_row cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=B_row cyclic factor=8 dim=1

      for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        A_row[j] = A[i][j];
        B_row[j] = B[i][j];
      }

      for (j = 0; j < n; j++)
	{
#pragma HLS PIPELINE II=1
	  acc_tmp = A_row[j] * x_local[j] + acc_tmp;
	  acc_y = B_row[j] * x_local[j] + acc_y;
	}

      tmp[i] = acc_tmp;
      y[i] = alpha * acc_tmp + beta * acc_y;
    }

}

#include "gramschmidt.h"


void kernel_gramschmidt( 
			double A[ M + 0][N + 0],
			double R[ N + 0][N + 0],
			double Q[ M + 0][N + 0])
{
#pragma HLS INLINE off

    const int m = M;
    const int n = N;

  int i, j, k;

  double nrm;

  for (k = 0; k < n; k++)
    {
      nrm = 0.0;
    nrm_loop:
      for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
        nrm += A[i][k] * A[i][k];
      }
      R[k][k] = sqrt(nrm);

    q_loop:
      for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
        Q[i][k] = A[i][k] / R[k][k];
      }

    j_loop:
      for (j = k + 1; j < n; j++)
	{
	  double r_acc = 0.0;
	r_loop:
	  for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
	    r_acc += Q[i][k] * A[i][j];
	  }
	  R[k][j] = r_acc;

	a_loop:
	  for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
	    A[i][j] = A[i][j] - Q[i][k] * r_acc;
	  }
	}
    }

}

extern "C" {
void workload(
			double A[ M + 0][N + 0],
			double R[ N + 0][N + 0],
			double Q[ M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=R offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=Q offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=R bundle=control
#pragma HLS INTERFACE s_axilite port=Q bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_gramschmidt(A, R, Q);
}
}

#include "jacobi-1d.h"

void kernel_jacobi_1d(

			    double A[ N + 0],
			    double B[ N + 0])
{


    const int n = N;
    const int tsteps = TSTEPS;

  int t, i;

  for (t = 0; t < tsteps; t++)
    {
    update_B:
      for (i = 1; i < n - 1; i++) {
#pragma HLS PIPELINE II=1
	B[i] = 0.33333 * (A[i-1] + A[i] + A[i + 1]);
      }
    update_A:
      for (i = 1; i < n - 1; i++) {
#pragma HLS PIPELINE II=1
	A[i] = 0.33333 * (B[i-1] + B[i] + B[i + 1]);
      }
    }

}

extern "C" {
void workload(
			    double A[ N + 0],
			    double B[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_jacobi_1d(A, B);
}
}

#include "jacobi-2d.h"

void kernel_jacobi_2d(

			    double A[ N + 0][N + 0],
			    double B[ N + 0][N + 0])
{
#pragma HLS INLINE off

    const int n = N;
    const int tsteps = TSTEPS;

  int t, i, j;

  for (t = 0; t < tsteps; t++)
    {
    stencil_B_i:
      for (i = 1; i < n - 1; i++)
      stencil_B_j:
	for (j = 1; j < n - 1; j++)
	  {
#pragma HLS PIPELINE II=1
	  B[i][j] = 0.2 * (A[i][j] + A[i][j-1] + A[i][1+j] + A[1+i][j] + A[i-1][j]);
	  }
    stencil_A_i:
      for (i = 1; i < n - 1; i++)
      stencil_A_j:
	for (j = 1; j < n - 1; j++)
	  {
#pragma HLS PIPELINE II=1
	  A[i][j] = 0.2 * (B[i][j] + B[i][j-1] + B[i][1+j] + B[1+i][j] + B[i-1][j]);
	  }
    }

}

extern "C" {
void workload(
			    double A[ N + 0][N + 0],
			    double B[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_jacobi_2d(A, B);
}
}

#include "lu.h"


void kernel_lu(
	       double A[ N + 0][N + 0])
{
#pragma HLS INLINE off

    const int n = N;

  int i, j, k;

  for (i = 0; i < n; i++) {
    for (j = 0; j <i; j++) {
       for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
          A[i][j] -= A[i][k] * A[k][j];
       }
        A[i][j] /= A[j][j];
    }
   for (j = i; j < n; j++) {
       for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
          A[i][j] -= A[i][k] * A[k][j];
       }
    }
  }
}

extern "C" {
void workload(
	       double A[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

  kernel_lu(A);
}
}

#include "ludcmp.h"


extern "C" {
void kernel_ludcmp(
		   double A[ N + 0][N + 0],
		   double b[ N + 0],
		   double x[ N + 0],
		   double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=b offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=b bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j, k;

  double w;

  for (i = 0; i < n; i++) {
    for (j = 0; j <i; j++) {
       w = A[i][j];
       for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
          w -= A[i][k] * A[k][j];
       }
        A[i][j] = w / A[j][j];
    }
   for (j = i; j < n; j++) {
       w = A[i][j];
       for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
          w -= A[i][k] * A[k][j];
       }
       A[i][j] = w;
    }
  }

  for (i = 0; i < n; i++) {
     w = b[i];
     for (j = 0; j < i; j++) {
#pragma HLS PIPELINE II=1
        w -= A[i][j] * y[j];
     }
     y[i] = w;
  }

   for (i = n-1; i >=0; i--) {
     w = y[i];
     for (j = i+1; j < n; j++) {
#pragma HLS PIPELINE II=1
        w -= A[i][j] * x[j];
     }
     x[i] = w / A[i][i];
  }

}
}

#include "mvt.h"

void kernel_mvt(
		double x1[ N + 0],
		double x2[ N + 0],
		double y_1[ N + 0],
		double y_2[ N + 0],
		double A[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=x1  offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=x2  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=y_1 offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=y_2 offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=x1  bundle=control
#pragma HLS INTERFACE s_axilite port=x2  bundle=control
#pragma HLS INTERFACE s_axilite port=y_1 bundle=control
#pragma HLS INTERFACE s_axilite port=y_2 bundle=control
#pragma HLS INTERFACE s_axilite port=A   bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    int i, j;

    // Local staging buffers for reuse across iterations
    double l_x1[N];
    double l_x2[N];
    double l_y1[N];
    double l_y2[N];
#pragma HLS ARRAY_PARTITION variable=l_y1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_y2 cyclic factor=8 dim=1

    // Stage inputs into local memory
    load_loop: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        l_x1[i] = x1[i];
        l_x2[i] = x2[i];
        l_y1[i] = y_1[i];
        l_y2[i] = y_2[i];
    }

    // First MV: x1[i] += A[i][j] * y_1[j]  (row-major friendly)
    mvt1_i: for (i = 0; i < n; i++) {
        double acc = l_x1[i];
        mvt1_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
            acc += A[i][j] * l_y1[j];
        }
        l_x1[i] = acc;
    }

    // Second MV: x2[i] += A[j][i] * y_2[j]
    mvt2_i: for (i = 0; i < n; i++) {
        double acc = l_x2[i];
        mvt2_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            acc += A[j][i] * l_y2[j];
        }
        l_x2[i] = acc;
    }

    // Write back results
    store_loop: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x1[i] = l_x1[i];
        x2[i] = l_x2[i];
    }
}

#include "nussinov.h"


void kernel_nussinov( char seq[ N + 0],
			   int table[ N + 0][N + 0])
{
#pragma HLS INLINE off

    const int n = N;

  int i, j, k;

 for (i = n-1; i >= 0; i--) {
  for (j=i+1; j<n; j++) {

   if (j-1>=0)
      table[i][j] = ((table[i][j] >= table[i][j-1]) ? table[i][j] : table[i][j-1]);
   if (i+1<n)
      table[i][j] = ((table[i][j] >= table[i+1][j]) ? table[i][j] : table[i+1][j]);

   if (j-1>=0 && i+1<n) {

     if (i<j-1)
        table[i][j] = ((table[i][j] >= table[i+1][j-1]+(((seq[i])+(seq[j])) == 3 ? 1 : 0)) ? table[i][j] : table[i+1][j-1]+(((seq[i])+(seq[j])) == 3 ? 1 : 0));
     else
        table[i][j] = ((table[i][j] >= table[i+1][j-1]) ? table[i][j] : table[i+1][j-1]);
   }

   for (k=i+1; k<j; k++) {
#pragma HLS PIPELINE II=1
      table[i][j] = ((table[i][j] >= table[i][k] + table[k+1][j]) ? table[i][j] : table[i][k] + table[k+1][j]);
   }
  }
 }

}

extern "C" {
void workload( char seq[ N + 0],
			   int table[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=seq   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=table offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=seq    bundle=control
#pragma HLS INTERFACE s_axilite port=table  bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_nussinov(seq, table);
}
}

#include "symm.h"


void kernel_symm( 
		 double alpha,
		 double beta,
		 double C[ M + 0][N + 0],
		 double A[ M + 0][M + 0],
		 double B[ M + 0][N + 0])
{
#pragma HLS INLINE off

    const int m = M;
    const int n = N;

  int i, j, k;
  double temp2;

 loop_i: for (i = 0; i < m; i++)
  {
   loop_j: for (j = 0; j < n; j++ )
    {
#pragma HLS PIPELINE II=1
        temp2 = 0;
     loop_k: for (k = 0; k < i; k++) {
           C[k][j] += alpha*B[i][j] * A[i][k];
           temp2 += B[k][j] * A[i][k];
        }
        C[i][j] = beta * C[i][j] + alpha*B[i][j] * A[i][i] + alpha * temp2;
     }
  }

}

extern "C" {
void workload(
		 double alpha,
		 double beta,
		 double C[ M + 0][N + 0],
		 double A[ M + 0][M + 0],
		 double B[ M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2

#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=C     bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=B     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_symm(alpha, beta, C, A, B);
}
}

#include "syr2k.h"


void kernel_syr2k( 
		  double alpha,
		  double beta,
		  double C[ N + 0][N + 0],
		  double A[ N + 0][M + 0],
		  double B[ N + 0][M + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=C     bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=B     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int m = M;

  int i, j, k;

  // Local staging buffers for reuse / parallel access
  double a_row[M];
  double b_row[M];
#pragma HLS ARRAY_PARTITION variable=a_row cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=b_row cyclic factor=8 dim=1

  double c_row[N];
#pragma HLS ARRAY_PARTITION variable=c_row cyclic factor=8 dim=1

  for (i = 0; i < n; i++) {

    // Stage A[i][*] and B[i][*] for reuse across the k/j loops
  load_ai:
    for (k = 0; k < m; k++) {
#pragma HLS PIPELINE II=1
      a_row[k] = A[i][k];
      b_row[k] = B[i][k];
    }

    // Stage current C row (only [0..i] valid, but load full for simplicity)
  load_c:
    for (j = 0; j <= i; j++) {
#pragma HLS PIPELINE II=1
      c_row[j] = C[i][j] * beta;
    }

  k_loop:
    for (k = 0; k < m; k++) {
      double bi = b_row[k];
      double ai = a_row[k];
    j_loop:
      for (j = 0; j <= i; j++) {
#pragma HLS PIPELINE II=1
        c_row[j] += A[j][k]*alpha*bi + B[j][k]*alpha*ai;
      }
    }

    // Write back the computed C row
  store_c:
    for (j = 0; j <= i; j++) {
#pragma HLS PIPELINE II=1
      C[i][j] = c_row[j];
    }
  }

}

#include "syrk.h"

void kernel_syrk(
		 double alpha,
		 double beta,
		 double C[ N + 0][N + 0],
		 double A[ N + 0][M + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int m = M;

    int i, j, k;

    // Local buffers to enable reuse and parallel access
    static double A_local[N][M];
#pragma HLS ARRAY_PARTITION variable=A_local cyclic factor=8 dim=2
    static double C_local[N][N];
#pragma HLS ARRAY_PARTITION variable=C_local cyclic factor=8 dim=2

    // Stage A into local memory
    LOAD_A_I:
    for (i = 0; i < n; i++) {
        LOAD_A_K:
        for (k = 0; k < m; k++) {
#pragma HLS PIPELINE II=1
            A_local[i][k] = A[i][k];
        }
    }

    // Stage C into local memory
    LOAD_C_I:
    for (i = 0; i < n; i++) {
        LOAD_C_J:
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            C_local[i][j] = C[i][j];
        }
    }

    // Compute on local buffers
    COMPUTE_I:
    for (i = 0; i < n; i++) {
        SCALE_J:
        for (j = 0; j <= i; j++) {
#pragma HLS PIPELINE II=1
            C_local[i][j] *= beta;
        }
        COMPUTE_K:
        for (k = 0; k < m; k++) {
            double a_ik = A_local[i][k];
            COMPUTE_J:
            for (j = 0; j <= i; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
                C_local[i][j] += alpha * a_ik * A_local[j][k];
            }
        }
    }

    // Write back C
    STORE_C_I:
    for (i = 0; i < n; i++) {
        STORE_C_J:
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            C[i][j] = C_local[i][j];
        }
    }
}

#include "trisolv.h"


void kernel_trisolv(
		    double L[ N + 0][N + 0],
		    double x[ N + 0],
		    double b[ N + 0])
{
#pragma HLS INLINE off

    const int n = N;

  int i, j;

  for (i = 0; i < n; i++)
    {
      double acc = b[i];
    inner:
      for (j = 0; j < i; j++)
        {
#pragma HLS PIPELINE II=1
          acc -= L[i][j] * x[j];
        }
      x[i] = acc / L[i][i];
    }

}

extern "C" {
void workload(
		    double L[ N + 0][N + 0],
		    double x[ N + 0],
		    double b[ N + 0])
{
#pragma HLS INTERFACE m_axi port=L offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=b offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=L bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=b bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_trisolv(L, x, b);
}
}

#include "trmm.h"


void kernel_trmm( 
		 double alpha,
		 double A[ M + 0][M + 0],
		 double B[ M + 0][N + 0])
{


    const int m = M;
    const int n = N;

  int i, j, k;
  loop_i: for (i = 0; i < m; i++)
     loop_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        double acc = B[i][j];
        loop_k: for (k = i+1; k < m; k++) {
           acc += A[k][i] * B[k][j];
        }
        B[i][j] = alpha * acc;
     }

}

extern "C" {
void workload(
		 double alpha,
		 double A[ M + 0][M + 0],
		 double B[ M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_trmm(alpha, A, B);
}
